package com.graduation.library.domain;import com.graduation.library.auth.AuthService;import com.graduation.library.common.ApiException;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/borrows")public class BorrowController{private final BorrowRecordRepository repo;private final BookRepository books;private final AuthService auth;public BorrowController(BorrowRecordRepository r,BookRepository b,AuthService a){repo=r;books=b;auth=a;}public record Borrow(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long bookId){}@PostMapping@Transactional public BorrowRecord borrow(@jakarta.validation.Valid @RequestBody Borrow x){var u=auth.currentUser();var b=books.findById(x.bookId()).orElseThrow(()->ApiException.notFound("图书不存在"));if(b.getAvailableCopies()<=0)throw ApiException.badRequest("暂无可借副本");if(repo.existsByBookIdAndUserIdAndStatus(b.getId(),u.getId(),"BORROWED"))throw ApiException.badRequest("你已借阅该书");b.setAvailableCopies(b.getAvailableCopies()-1);books.save(b);var r=new BorrowRecord();r.setBookId(b.getId());r.setUserId(u.getId());r.setBorrowedAt(LocalDateTime.now());r.setDueAt(LocalDateTime.now().plusDays(30));r.setStatus("BORROWED");return repo.save(r);}@PostMapping("/{id}/return")@Transactional public BorrowRecord ret(@PathVariable Long id){var u=auth.currentUser();var r=repo.findById(id).orElseThrow(()->ApiException.notFound("借阅记录不存在"));if(!"ADMIN".equals(u.getRole())&&!u.getId().equals(r.getUserId()))throw ApiException.forbidden("无权归还该记录");if(!"BORROWED".equals(r.getStatus()))throw ApiException.badRequest("该记录已归还");var b=books.findById(r.getBookId()).orElseThrow();b.setAvailableCopies(Math.min(b.getTotalCopies(),b.getAvailableCopies()+1));books.save(b);r.setReturnedAt(LocalDateTime.now());r.setStatus("RETURNED");return repo.save(r);}@GetMapping public List<BorrowRecord>list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}}
